// === Tab: mySketch ===
function tixy(t, i, x, y) {
	// here's the place to input your https://tixy.land/ formula.
	return sin(t-sqrt((x-7.5)**2+(y-6)**2));
}

let tixyShader;
let tixyImg;

function preload() {
	tixyShader = getTixyShader(this._renderer);
}

function setup() {
	let size = max(windowWidth, windowHeight);
	createCanvas(size, size, WEBGL);
	tixyImg = createImage(16, 16);
	tixyImg.loadPixels();
	noStroke();
}

function draw() {
	background(0);
	var maxDim = max(width, height) / 2.0;
	var t = millis()/1000.0;
	for (var i = 0; i < 256; i++) {
		var x = int(i % 16);
		var y = int(i / 16);
		var value = tixy(t, i, x, y);
		tixyImg.set(x, y, [map(value, -1.0, 1.0, 0, 255, true), 0, 0, 255]);
	}
	tixyImg.updatePixels();
	shader(tixyShader);
	tixyShader.setUniform('ti', tixyImg);
	rect(0, 0, maxDim*2, maxDim*2);
}

// === Tab: tixyShader ===
function getTixyShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;
			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float; // mediump makes smoothstep() act really weird on mobile webgl ¯\_(ツ)_/¯

		varying vec2 vTexCoord;
		uniform sampler2D ti;
		float map(float value, float min1, float max1, float min2, float max2) {
			return min2 + (value - min1) * (max2 - min2) / (max1 - min1);
		}
		void main() {
      vec2 vxy = vec2(vTexCoord.x, 1.0-vTexCoord.y);
			vec2 xy = floor(vxy*16.0)/16.0 + (0.5/16.0);
			float v = map(texture2D(ti, xy).x, 0.0, 1.0, -1.0, 1.0);
			float d = distance(xy, vxy)*32.0;
			vec3 col = sign(v)*vec3(1.0);
			col = mix(col, vec3(0.0), 1.0-smoothstep(0.0, 0.04, v-d));
			vec3 ncol = (-sign(v))*vec3(1.0, 0.243, 0.294);
			ncol = mix(ncol, vec3(0.0), smoothstep(0.0, 0.01, v+d));
			gl_FragColor = vec4(col+ncol, 1.0);
		}

	`;

	return createShader(vert, frag);
}

